    "hyph_upper": chal.upper().encode(),
    "simple": u.hex.encode(),
    "simple_upper": u.hex.upper().encode(),
    "bytes_be": u.bytes,
    "bytes_le": u.bytes_le,
    "int_dec": str(u.int).encode(),
    "braced": ("{"+chal+"}").encode(),
    "urn": ("urn:uuid:"+chal).encode(),
    "empty": b"",
}

for algo in ["sha256","sha512","sha384","sha224","sha1","md5","blake2s","blake2b","sha3_256","sha3_512","sha3_384","sha3_224","shake_128","shake_256","sm3","sha512_256","sha512_224"]:
    for rname, data in reps.items():
        try:
            if algo.startswith("shake"):
                h=hashlib.new(algo, data).hexdigest(32)  # 32 bytes = 64 hex
            elif algo=="blake2b":
                # try default (64 bytes) truncated and digest_size=32
                h1=hashlib.blake2b(data).hexdigest()[:64]
                h2=hashlib.blake2b(data, digest_size=32).hexdigest()
                if h1==expected_empty:
                    print(f"MATCH {algo} truncated {rname}")
                if h2==expected_empty:
                    print(f"MATCH {algo} digest32 {rname}")
                continue
            elif algo=="blake2s":
                h=hashlib.blake2s(data).hexdigest()
            else:
                h=hashlib.new(algo, data).hexdigest()
                # truncate if longer?
                if len(h)>64:
                    # check prefix and full? For sha512, full is 128, prefix 64?
                    if h[:64]==expected_empty:
                        print(f"MATCH {algo} truncated {rname} full {h}")
                    continue
                elif len(h)<64:
                    # e.g., md5 32, sha1 40, need to check? But expected is 64, so not match unless doubled?
                    continue
            if h==expected_empty:
                print(f"MATCH {algo} {rname}")
        except Exception as e:
            pass

print("done empty")

# Also try with secret "a" and challenge zeros: H("a"+challenge) etc.
# For empty, we tried H(challenge) alone. But what if formula is H(secret+challenge) with empty secret, then it's H(challenge) as above.
# If no match, then formula is not H(secret+challenge) with simple H.
# Let's also try HMAC with empty key? HMAC(empty, challenge) vs HMAC(challenge, empty)?
import hmac
for algo in ["sha256","sha512","sha1"]:
    for rname, data in reps.items():
        if rname=="empty": continue
        try:
            h1=hmac.new(b"", data, getattr(hashlib, algo)).hexdigest()
            if algo!="sha256":
                h1=h1[:64] if len(h1)>64 else h1
            if h1==expected_empty:
                print(f"MATCH hmac empty_key {algo} {rname}")
            h2=hmac.new(data, b"", getattr(hashlib, algo)).hexdigest()
            if algo!="sha256":
                h2=h2[:64] if len(h2)>64 else h2
            if h2==expected_empty:
                print(f"MATCH hmac empty_msg {algo} {rname}")
        except: pass
print("done hmac empty")
