for len_fmt in ["u8","u16le","u16be","u32le","u32be","u64le","u64be"]:
    for rname, ch in reps.items():
        ch_bytes = ch.encode() if isinstance(ch, str) else ch
        if len_fmt=="u8":
            lb=b"\x00"
