            lb=b"\x00\x00"
        elif len_fmt=="u16be":
            lb=b"\x00\x00"
        elif len_fmt=="u32le":
            lb=b"\x00\x00\x00\x00"
        elif len_fmt=="u32be":
            lb=b"\x00\x00\x00\x00"
        elif len_fmt=="u64le":
