            if h==expected_empty:
                print(f"MATCH len {len_fmt} {rname} {name}")

print("done len")

# Try with challenge len prefix? Challenge len? For hyph, len=36, for simple len=32, for bytes len=16
# Try H(secret_len + secret + challenge_len + challenge)? For empty, secret_len=0, challenge_len=36/32/16
for rname, ch in reps.items():
    ch_bytes = ch.encode() if isinstance(ch, str) else ch
    ch_len=len(ch_bytes)
    for secret_len_fmt in ["u8","u32le"]:
        for chal_len_fmt in ["u8","u32le"]:
            def enc_len(n, fmt):
                if fmt=="u8":
