    print(f"testing {sec!r} {chal!r} exp {exp}")
    u=uuid.UUID(chal)
    for salt_rep, salt in [("hyph", chal.encode()), ("simple", u.hex.encode()), ("bytes", u.bytes)]:
        for iters in [1,2,10,100,1000,10000]:
