            let bind_addr = *sub.get_one::<IpAddr>("bind-addr").unwrap();
            let bind_tunnels = sub.get_one::<IpAddr>("bind-tunnels").copied();
            server::run(min_port, max_port, secret, bind_addr, bind_tunnels)
        }
        _ => unreachable!(),
    }
}

