                        .hide_env_values(true),
                ),
        )
        .subcommand(
            Command::new("server")
                .about("Runs the remote proxy server")
                .arg(
                    Arg::new("min-port")
                        .long("min-port")
                        .value_name("MIN_PORT")
                        .help("Minimum accepted TCP port number")
                        .env("BORE_MIN_PORT")
                        .default_value("1024")
                        .value_parser(clap::value_parser!(u16)),
                )
                .arg(
                    Arg::new("max-port")
                        .long("max-port")
                        .value_name("MAX_PORT")
                        .help("Maximum accepted TCP port number")
                        .env("BORE_MAX_PORT")
                        .default_value("65535")
                        .value_parser(clap::value_parser!(u16)),
                )
                .arg(
                    Arg::new("secret")
                        .short('s')
                        .long("secret")
                        .value_name("SECRET")
                        .help("Optional secret for authentication")
                        .env("BORE_SECRET")
                        .hide_env_values(true),
                )
                .arg(
                    Arg::new("bind-addr")
                        .long("bind-addr")
                        .value_name("BIND_ADDR")
                        .help("IP address to bind to, clients must reach this")
                        .default_value("0.0.0.0")
                        .value_parser(clap::value_parser!(IpAddr)),
                )
                .arg(
                    Arg::new("bind-tunnels")
                        .long("bind-tunnels")
                        .value_name("BIND_TUNNELS")
                        .help("IP address where tunnels will listen on, defaults to --bind-addr")
                        .value_parser(clap::value_parser!(IpAddr)),
                ),
        )
}

fn main() -> anyhow::Result<()> {
    let matches = cli().get_matches();
    match matches.subcommand() {
        Some(("local", sub)) => {
            let local_port = *sub.get_one::<u16>("local-port").unwrap();
            let local_host = sub.get_one::<String>("local-host").unwrap().clone();
            let to = sub.get_one::<String>("to").unwrap().clone();
            let port = *sub.get_one::<u16>("port").unwrap();
            let secret = sub.get_one::<String>("secret").cloned();
            client::run(local_port, local_host, to, port, secret)
        }
        Some(("server", sub)) => {
            let min_port = *sub.get_one::<u16>("min-port").unwrap();
            let max_port = *sub.get_one::<u16>("max-port").unwrap();
            if min_port > max_port {
                eprint!("error: port range is empty\n\nUsage: bore-cli <COMMAND>\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            let secret = sub.get_one::<String>("secret").cloned();
            let bind_addr = *sub.get_one::<IpAddr>("bind-addr").unwrap();
            let bind_tunnels = sub.get_one::<IpAddr>("bind-tunnels").copied();
            server::run(min_port, max_port, secret, bind_addr, bind_tunnels)
        }
        _ => unreachable!(),
    }
}

