pub fn run(
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: IpAddr,
    bind_tunnels: Option<IpAddr>,
) -> anyhow::Result<()> {
    let tunnel_ip = bind_tunnels.unwrap_or(bind_addr);
    // Bind control
    let listener = TcpListener::bind((bind_addr, 7835))?;
