fn handle_accept(
    mut stream: TcpStream,
    span: Span,
    id: Uuid,
    pending: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
    _secret: Option<String>,
) {
    logging::info_server(Some(&span), "forwarding connection", &[("id", id.to_string())]);
    let external_opt = {
        let mut map = pending.lock().unwrap();
        map.remove(&id)
    };
    match external_opt {
        None => {
            logging::warn_server(Some(&span), "missing connection", &[("id", id.to_string())]);
            logging::info_server(Some(&span), "connection exited", &[]);
            let _ = stream.shutdown(Shutdown::Both);
            return;
        }
        Some(mut external) => {
            // Proxy between external and stream (Accept connection)
            // Both are blocking TcpStreams. Use bidirectional copy with shutdown propagation.
            // Need to handle that external may have buffered data already (sent before Accept). Our proxy will read it. Good.
            match proxy_bidirectional(&mut external, &mut stream) {
                Ok(()) => {
                    logging::info_server(Some(&span), "connection exited", &[]);
                }
                Err(e) => {
                    // e is io::Error, log its Display (e.g., "Connection reset by peer (os error 104)")
                    logging::warn_server(Some(&span), "connection exited with error", &[("err", e.to_string())]);
                }
            }
            let _ = external.shutdown(Shutdown::Both);
            let _ = stream.shutdown(Shutdown::Both);
        }
    }
}

fn proxy_bidirectional(a: &mut TcpStream, b: &mut TcpStream) -> std::io::Result<()> {
    // a = external, b = accept
    // Clone for threads
    let mut a_read = a.try_clone()?;
    let mut a_write = a.try_clone()?;
    let mut b_read = b.try_clone()?;
    let mut b_write = b.try_clone()?;
    // Need originals for shutdown? Actually clones share same socket, shutdown on any affects all. Good.
    // Thread 1: a -> b (read from a_read, write to b_write). On a EOF, shutdown b_write's write half (i.e., b.shutdown(Write))? But b_write is clone, shutdown(Write) on it will shutdown write half of b (send FIN to client). Good.
    // Thread 2: b -> a similarly.
    // Use scoped threads? Use std::thread::spawn + join, collect errors.
    // If either direction fails with error (not EOF), return that error. If both succeed (EOFs), return Ok.
    // How to determine error vs EOF? `copy` returns bytes copied, no error on EOF. Errors are io errors (e.g., reset). Good.
    // Implement copy loop manually to handle shutdown.

    let h1 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            match a_read.read(&mut buf) {
                Ok(0) => {
                    // EOF from a, shutdown b's write
                    let _ = b_write.shutdown(Shutdown::Write);
                    break Ok(());
                }
                Ok(n) => {
                    if let Err(e) = b_write.write_all(&buf[..n]) {
                        let _ = b_write.shutdown(Shutdown::Both);
                        // Also shutdown a? To unblock other thread? The other thread is reading from b, which may still be open. If we fail to write to b (e.g., b closed), other thread may still be reading from b (which is closed)? It will get EOF/error and exit. Good.
                        break Err(e);
                    }
                }
                Err(e) => {
                    let _ = b_write.shutdown(Shutdown::Both);
                    break Err(e);
                }
            }
        }
    });

    let h2 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            match b_read.read(&mut buf) {
                Ok(0) => {
                    let _ = a_write.shutdown(Shutdown::Write);
                    break Ok(());
                }
                Ok(n) => {
                    if let Err(e) = a_write.write_all(&buf[..n]) {
                        let _ = a_write.shutdown(Shutdown::Both);
                        break Err(e);
                    }
                }
                Err(e) => {
                    let _ = a_write.shutdown(Shutdown::Both);
                    break Err(e);
                }
            }
        }
    });

    let r1 = h1.join().unwrap_or(Err(std::io::Error::new(std::io::ErrorKind::Other, "thread panic")));
    let r2 = h2.join().unwrap_or(Err(std::io::Error::new(std::io::ErrorKind::Other, "thread panic")));

    // If either failed with error (not just EOF), return that error. But need to distinguish EOF (Ok) vs error (Err).
    // However, when one direction hits EOF and shuts down other's write, the other direction may still be transferring data (half-close case). In half-close test, external shutdown WR (EOF on a->b direction), but b->a direction still needed to transfer response. Our implementation: h1 sees EOF from a, shuts down b's write, exits Ok. h2 continues reading from b (which still has data? Actually b is Accept connection to client; after h1 shuts down b's write, b's read is still open? Shutdown(Write) only shuts down write half, read still open. Good. So h2 can still read response from b and write to a (but a's write? a is external, which shutdown WR (i.e., external closed its write, but its read still open? Actually external did shutdown(WR), meaning external will no longer send, but still wants to receive. Server's `a` socket's read will see EOF (since external closed write), but `a`'s write is still open (to send response to external). Good. So h2 reading from b and writing to a should succeed. Good.
    // After both finish, if either Err, return Err. But what if one Err is due to other side closing? E.g., normal close: external closes fully (both directions), both threads will see EOF? Or one will see EOF, other will see EOF? Both Ok. Good.
    // If local-down case: client closes Accept connection abruptly (RST?) after failing to connect to local. Server's `b` (Accept) will see RST on read or write? h1 trying to write to b (from a) may fail with reset, h2 reading from b may fail with reset. Both Err with same? Return first Err.
    // For normal close, both Ok, return Ok.
    // For error case, return Err with first error? Which one? Original server for local-down logged `Connection reset by peer (os error 104)` (from proxy). That could be from either direction. Our code returns r1 Err if any, else r2 Err? Let's prioritize r1? Or whichever is Err? If both Err, return r1? Good.
    if let Err(e) = r1 {
        return Err(e);
    }
    if let Err(e) = r2 {
        return Err(e);
    }
    Ok(())
}
