        match stream {
            Ok(s) => {
                let peer = s.peer_addr().map(|a| a.to_string()).unwrap_or_else(|_| "?".to_string());
                let span = Span::control(peer);
                logging::info_server(Some(&span), "incoming connection", &[]);
                let secret = secret.clone();
                let pending = pending.clone();
                std::thread::spawn(move || {
                    handle_connection(s, span, secret, min_port, max_port, tunnel_ip, pending);
                });
            }
            Err(e) => {
                // Accept error: original probably ignores? Just continue.
                // Don't log? Or log? Unlikely tested. Continue.
                let _ = e;
                continue;
            }
        }
    }
    Ok(())
}

fn handle_connection(
    stream: TcpStream,
    span: Span,
    secret: Option<String>,
    min_port: u16,
    max_port: u16,
    tunnel_ip: IpAddr,
    pending: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
) {
    // Set up: need mutable stream for reading/writing
    // For handshake, use timeout reads
    if secret.is_some() {
        handle_with_secret(stream, span, secret.unwrap(), min_port, max_port, tunnel_ip, pending);
    } else {
        handle_no_secret(stream, span, min_port, max_port, tunnel_ip, pending);
    }
}

fn send_error(stream: &mut TcpStream, msg: &str) {
    let err = ServerMessage::Error(msg.to_string());
    let _ = shared::send_message(stream, &err);
}

fn handle_no_secret(
    mut stream: TcpStream,
    span: Span,
    min_port: u16,
    max_port: u16,
    tunnel_ip: IpAddr,
    pending: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
) {
    // Read first message with timeout 3s, expecting Hello or Accept (or Authenticate -> unexpected)
    let first: anyhow::Result<ClientMessage> = shared::recv_message_timeout(&stream, Duration::from_secs(3));
    match first {
        Err(e) => {
            let msg = format!("{:?}", e);
            // Check if timeout, eof, or parse error
            // Our recv_message_timeout returns:
            // - timeout: "timed out waiting for initial message" + "deadline has elapsed"
            // - eof: "eof"
            // - parse: "unable to parse message" + details
            // Need to distinguish. Check e.to_string()? For timeout, e.to_string() is "timed out waiting for initial message"? Actually anyhow Display for outer? Let's check: anyhow!("deadline").context("timed out...") Display is "timed out..."? And Debug is "timed out...\nCaused by:\n deadline..."? Our code does `format!("{:?}", e)` which is Debug. Better to check via `e.to_string()` (Display) which is outer.
            let display = format!("{}", e);
            if display == "timed out waiting for initial message" {
                logging::warn_server(Some(&span), "connection exited with error", &[("err", "timed out waiting for initial message".to_string())]);
                // No separate INFO, just close
            } else if display == "eof" {
                logging::info_server(Some(&span), "connection exited", &[]);
            } else if display == "unable to parse message" {
                logging::warn_server(Some(&span), "connection exited with error", &[("err", "unable to parse message".to_string())]);
            } else {
                // Other read error? Treat as connection exited? Or with error?
                // For "read error" + os error? Unlikely. Log with error?
                // Original for read errors (e.g., connection reset during handshake)? What would it log? Possibly `connection exited with error err=<os error>`? Let's do that.
                // But need to get os error string? Our e is anyhow with context "read error" + os error. Display is "read error", not os. Hmm. Better to log os error directly?
                // For simplicity, log `connection exited` INFO? Or WARN with e?
                // Let's check what original does for read error during handshake: Hard to trigger. For now, log INFO `connection exited`.
                logging::info_server(Some(&span), "connection exited", &[]);
            }
            let _ = stream.shutdown(Shutdown::Both);
            return;
        }
        Ok(msg) => {
            match msg {
                ClientMessage::Authenticate(_) => {
                    logging::warn_server(Some(&span), "unexpected authenticate", &[]);
                    logging::info_server(Some(&span), "connection exited", &[]);
                    let _ = stream.shutdown(Shutdown::Both);
                    return;
                }
                ClientMessage::Hello(port) => {
                    handle_hello(stream, span, port, min_port, max_port, tunnel_ip, pending, None);
                    return;
                }
                ClientMessage::Accept(id) => {
                    handle_accept(stream, span, id, pending, None);
                    return;
                }
            }
        }
    }
}

fn handle_with_secret(
    mut stream: TcpStream,
    span: Span,
    secret: String,
    min_port: u16,
    max_port: u16,
    tunnel_ip: IpAddr,
    pending: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
) {
    // Send Challenge
    let challenge = Uuid::new_v4();
    let chal_msg = ServerMessage::Challenge(challenge);
    if shared::send_message(&mut stream, &chal_msg).is_err() {
        logging::info_server(Some(&span), "connection exited", &[]);
        return;
    }
    // Read first message with timeout, expecting Authenticate
    let first: anyhow::Result<ClientMessage> = shared::recv_message_timeout(&stream, Duration::from_secs(3));
    match first {
        Err(e) => {
            let display = format!("{}", e);
            if display == "timed out waiting for initial message" {
                logging::warn_server(Some(&span), "connection exited with error", &[("err", "timed out waiting for initial message".to_string())]);
            } else if display == "eof" {
                logging::info_server(Some(&span), "connection exited", &[]);
            } else if display == "unable to parse message" {
                // For secret handshake, parse error on first message -> send Error + handshake failed
                send_error(&mut stream, "unable to parse message");
                logging::warn_server(Some(&span), "server handshake failed", &[("err", "unable to parse message".to_string())]);
                logging::info_server(Some(&span), "connection exited", &[]);
            } else {
                logging::info_server(Some(&span), "connection exited", &[]);
            }
            let _ = stream.shutdown(Shutdown::Both);
            return;
        }
        Ok(msg) => {
            match msg {
                ClientMessage::Authenticate(provided) => {
                    if !shared::verify_auth(&secret, &challenge, &provided) {
                        send_error(&mut stream, "invalid secret");
                        logging::warn_server(Some(&span), "server handshake failed", &[("err", "invalid secret".to_string())]);
                        logging::info_server(Some(&span), "connection exited", &[]);
                        let _ = stream.shutdown(Shutdown::Both);
                        return;
                    }
                    // Auth ok, read second message (Hello or Accept) with timeout? What timeout? Original: After Auth, second message also has timeout? In our test, after Auth, we waited 0.3s then sent Hello, succeeded. What if we wait longer than 3s after Auth before sending Hello? Does server timeout? Likely yes, same 3s? Or maybe no timeout for second? Let's assume same 3s overall? Actually original's handshake timeout might be for each message? Or for entire handshake? Hard to tell. For simplicity, use 3s for second as well.
                    // But what does original log on timeout for second message? Probably same `timed out...`? Or `unable to parse`? We haven't tested timeout for second. Let's assume same as first: `timed out...` with WARN `connection exited with error` (not handshake failed)? Or handshake failed? For second message after Auth, timeout should probably be `connection exited with error` (like parse error after Auth, which was `connection exited with error`, not handshake failed). Good. So second message timeout -> `connection exited with error` with `timed out...`? Let's implement that.
                    let second: anyhow::Result<ClientMessage> = shared::recv_message_timeout(&stream, Duration::from_secs(3));
                    match second {
                        Err(e2) => {
                            let d2 = format!("{}", e2);
                            if d2 == "timed out waiting for initial message" {
                                logging::warn_server(Some(&span), "connection exited with error", &[("err", "timed out waiting for initial message".to_string())]);
                            } else if d2 == "eof" {
                                logging::info_server(Some(&span), "connection exited", &[]);
                            } else if d2 == "unable to parse message" {
                                logging::warn_server(Some(&span), "connection exited with error", &[("err", "unable to parse message".to_string())]);
                            } else {
                                logging::info_server(Some(&span), "connection exited", &[]);
                            }
                            let _ = stream.shutdown(Shutdown::Both);
                            return;
                        }
                        Ok(msg2) => {
                            match msg2 {
                                ClientMessage::Authenticate(_) => {
                                    logging::warn_server(Some(&span), "unexpected authenticate", &[]);
                                    logging::info_server(Some(&span), "connection exited", &[]);
                                    let _ = stream.shutdown(Shutdown::Both);
                                    return;
                                }
                                ClientMessage::Hello(port) => {
                                    handle_hello(stream, span, port, min_port, max_port, tunnel_ip, pending, Some(secret));
                                    return;
                                }
                                ClientMessage::Accept(id) => {
                                    handle_accept(stream, span, id, pending, Some(secret));
                                    return;
                                }
                            }
                        }
                    }
                }
                ClientMessage::Hello(_) | ClientMessage::Accept(_) => {
                    send_error(&mut stream, "server requires secret, but no secret was provided");
                    logging::warn_server(Some(&span), "server handshake failed", &[("err", "server requires secret, but no secret was provided".to_string())]);
                    logging::info_server(Some(&span), "connection exited", &[]);
                    let _ = stream.shutdown(Shutdown::Both);
                    return;
                }
            }
        }
    }
}

