fn handle_accept(
    mut stream: TcpStream,
    span: Span,
    id: Uuid,
    pending: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
    _secret: Option<String>,
) {
    logging::info_server(Some(&span), "forwarding connection", &[("id", id.to_string())]);
    let external_opt = {
        let mut map = pending.lock().unwrap();
        map.remove(&id)
    };
    match external_opt {
        None => {
            logging::warn_server(Some(&span), "missing connection", &[("id", id.to_string())]);
            logging::info_server(Some(&span), "connection exited", &[]);
            let _ = stream.shutdown(Shutdown::Both);
            return;
        }
        Some(mut external) => {
            // Proxy between external and stream (Accept connection)
            // Both are blocking TcpStreams. Use bidirectional copy with shutdown propagation.
            // Need to handle that external may have buffered data already (sent before Accept). Our proxy will read it. Good.
            match proxy_bidirectional(&mut external, &mut stream) {
                Ok(()) => {
                    logging::info_server(Some(&span), "connection exited", &[]);
                }
                Err(e) => {
                    // e is io::Error, log its Display (e.g., "Connection reset by peer (os error 104)")
                    logging::warn_server(Some(&span), "connection exited with error", &[("err", e.to_string())]);
                }
            }
            let _ = external.shutdown(Shutdown::Both);
            let _ = stream.shutdown(Shutdown::Both);
        }
    }
}

fn proxy_bidirectional(a: &mut TcpStream, b: &mut TcpStream) -> std::io::Result<()> {
    // a = external, b = accept
    // Clone for threads
    let mut a_read = a.try_clone()?;
    let mut a_write = a.try_clone()?;
    let mut b_read = b.try_clone()?;
    let mut b_write = b.try_clone()?;
    // Need originals for shutdown? Actually clones share same socket, shutdown on any affects all. Good.
    // Thread 1: a -> b (read from a_read, write to b_write). On a EOF, shutdown b_write's write half (i.e., b.shutdown(Write))? But b_write is clone, shutdown(Write) on it will shutdown write half of b (send FIN to client). Good.
    // Thread 2: b -> a similarly.
    // Use scoped threads? Use std::thread::spawn + join, collect errors.
    // If either direction fails with error (not EOF), return that error. If both succeed (EOFs), return Ok.
