                    logging::warn_client(Some(&span), "connection exited with error", &[("err", "unable to parse message".to_string())]);
                } else {
                    logging::info_client(Some(&span), "connection exited", &[]);
                }
                let _ = server_stream.shutdown(Shutdown::Both);
                return;
            }
        }
    } else {
        // No secret: send Accept immediately
        let accept_msg = ClientMessage::Accept(id);
        if shared::send_message(&mut server_stream, &accept_msg).is_err() {
            logging::warn_client(Some(&span), "connection exited with error", &[("err", "failed to send accept".to_string())]);
            let _ = server_stream.shutdown(Shutdown::Both);
            return;
        }
    }

    // Connect to local
    let local_addr_str = format!("{}:{}", local_host, local_port);
    let mut local_stream = match TcpStream::connect(&local_addr_str) {
        Ok(s) => s,
        Err(_) => {
            logging::warn_client(Some(&span), "connection exited with error", &[("err", format!("could not connect to {}", local_addr_str))]);
            let _ = server_stream.shutdown(Shutdown::Both);
            return;
        }
    };

    // Proxy between server_stream and local_stream
    match proxy_bidirectional(&mut server_stream, &mut local_stream) {
        Ok(()) => {
            logging::info_client(Some(&span), "connection exited", &[]);
        }
        Err(e) => {
            logging::warn_client(Some(&span), "connection exited with error", &[("err", e.to_string())]);
        }
    }
    let _ = server_stream.shutdown(Shutdown::Both);
    let _ = local_stream.shutdown(Shutdown::Both);
}

fn proxy_bidirectional(a: &mut TcpStream, b: &mut TcpStream) -> std::io::Result<()> {
    let mut a_read = a.try_clone()?;
    let mut a_write = a.try_clone()?;
    let mut b_read = b.try_clone()?;
    let mut b_write = b.try_clone()?;

    let h1 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            match a_read.read(&mut buf) {
                Ok(0) => {
                    let _ = b_write.shutdown(Shutdown::Write);
                    break Ok(());
                }
                Ok(n) => {
                    if let Err(e) = b_write.write_all(&buf[..n]) {
                        let _ = b_write.shutdown(Shutdown::Both);
                        break Err(e);
                    }
                }
                Err(e) => {
                    let _ = b_write.shutdown(Shutdown::Both);
                    break Err(e);
                }
            }
        }
    });

    let h2 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            match b_read.read(&mut buf) {
                Ok(0) => {
                    let _ = a_write.shutdown(Shutdown::Write);
                    break Ok(());
                }
                Ok(n) => {
                    if let Err(e) = a_write.write_all(&buf[..n]) {
                        let _ = a_write.shutdown(Shutdown::Both);
                        break Err(e);
                    }
                }
                Err(e) => {
                    let _ = a_write.shutdown(Shutdown::Both);
                    break Err(e);
                }
            }
        }
    });

    let r1 = h1.join().unwrap_or(Err(std::io::Error::new(std::io::ErrorKind::Other, "thread panic")));
    let r2 = h2.join().unwrap_or(Err(std::io::Error::new(std::io::ErrorKind::Other, "thread panic")));

    if let Err(e) = r1 {
        return Err(e);
    }
    if let Err(e) = r2 {
        return Err(e);
    }
    Ok(())
}
