fn handle_proxy(
    id: Uuid,
    to: String,
    secret: Option<String>,
    local_host: String,
    local_port: u16,
) {
    let span = Span::proxy(id.to_string());
    logging::info_client(Some(&span), "new connection", &[]);
    // Connect to server for Accept
    let addr_str = format!("{}:7835", to);
    let mut server_stream = match TcpStream::connect(&addr_str) {
        Ok(s) => s,
        Err(e) => {
            // What does original do if Accept connection to server fails? E.g., server down after Connection notification? Unlikely. Log `connection exited with error err=<os error>`? Or `could not connect...`? Let's log with os error.
            logging::warn_client(Some(&span), "connection exited with error", &[("err", e.to_string())]);
            return;
        }
    };

    // Handle secret for Accept connection
    if let Some(sec) = secret.clone() {
        // Wait for Challenge with timeout 3s
        let chal_res: anyhow::Result<ServerMessage> = shared::recv_message_timeout(&server_stream, Duration::from_secs(3));
        match chal_res {
            Ok(ServerMessage::Challenge(challenge)) => {
                let auth = shared::compute_auth(&sec, &challenge);
                let auth_msg = ClientMessage::Authenticate(auth);
                if shared::send_message(&mut server_stream, &auth_msg).is_err() {
                    logging::warn_client(Some(&span), "connection exited with error", &[("err", "failed to send authenticate".to_string())]);
                    let _ = server_stream.shutdown(Shutdown::Both);
                    return;
                }
                // Send Accept
                let accept_msg = ClientMessage::Accept(id);
                if shared::send_message(&mut server_stream, &accept_msg).is_err() {
                    logging::warn_client(Some(&span), "connection exited with error", &[("err", "failed to send accept".to_string())]);
                    let _ = server_stream.shutdown(Shutdown::Both);
                    return;
                }
                // No response expected for Accept (server immediately proxies, no Hello). Good. Proceed to local connect and proxy.
            }
            Ok(_) => {
                // Expected Challenge, got something else. What does original do? Possibly log and exit? For Accept connection with secret, if server sends non-Challenge (shouldn't happen, since server with secret always sends Challenge for new connections), what? Could be server without secret (mismatch)? But control already succeeded with secret, so server must have secret, so Accept will also get Challenge. Good. So this shouldn't happen. For robustness, log error and exit.
                logging::warn_client(Some(&span), "connection exited with error", &[("err", "expected authentication challenge, but no secret was required".to_string())]);
                let _ = server_stream.shutdown(Shutdown::Both);
                return;
            }
            Err(e) => {
                let disp = format!("{}", e);
                if disp == "timed out waiting for initial message" {
                    logging::warn_client(Some(&span), "connection exited with error", &[("err", "timed out waiting for initial message".to_string())]);
                } else if disp == "eof" {
                    logging::info_client(Some(&span), "connection exited", &[]);
                } else if disp == "unable to parse message" {
                    // Parse error for Challenge? Original would probably log `unable to parse`? Or exit? For Accept handshake, parse error should log `connection exited with error err=unable to parse message`? Or `...`? Let's do that.
                    logging::warn_client(Some(&span), "connection exited with error", &[("err", "unable to parse message".to_string())]);
                } else {
                    logging::info_client(Some(&span), "connection exited", &[]);
                }
                let _ = server_stream.shutdown(Shutdown::Both);
                return;
            }
        }
    } else {
        // No secret: send Accept immediately
        let accept_msg = ClientMessage::Accept(id);
        if shared::send_message(&mut server_stream, &accept_msg).is_err() {
            logging::warn_client(Some(&span), "connection exited with error", &[("err", "failed to send accept".to_string())]);
            let _ = server_stream.shutdown(Shutdown::Both);
            return;
        }
    }

    // Connect to local
    let local_addr_str = format!("{}:{}", local_host, local_port);
    let mut local_stream = match TcpStream::connect(&local_addr_str) {
        Ok(s) => s,
        Err(_) => {
            logging::warn_client(Some(&span), "connection exited with error", &[("err", format!("could not connect to {}", local_addr_str))]);
            let _ = server_stream.shutdown(Shutdown::Both);
            return;
        }
    };

    // Proxy between server_stream and local_stream
    match proxy_bidirectional(&mut server_stream, &mut local_stream) {
        Ok(()) => {
            logging::info_client(Some(&span), "connection exited", &[]);
        }
        Err(e) => {
            logging::warn_client(Some(&span), "connection exited with error", &[("err", e.to_string())]);
        }
    }
    let _ = server_stream.shutdown(Shutdown::Both);
    let _ = local_stream.shutdown(Shutdown::Both);
}

fn proxy_bidirectional(a: &mut TcpStream, b: &mut TcpStream) -> std::io::Result<()> {
    let mut a_read = a.try_clone()?;
    let mut a_write = a.try_clone()?;
    let mut b_read = b.try_clone()?;
    let mut b_write = b.try_clone()?;

    let h1 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            match a_read.read(&mut buf) {
                Ok(0) => {
                    let _ = b_write.shutdown(Shutdown::Write);
                    break Ok(());
                }
                Ok(n) => {
                    if let Err(e) = b_write.write_all(&buf[..n]) {
                        let _ = b_write.shutdown(Shutdown::Both);
                        break Err(e);
                    }
                }
                Err(e) => {
                    let _ = b_write.shutdown(Shutdown::Both);
                    break Err(e);
                }
            }
        }
    });

    let h2 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            match b_read.read(&mut buf) {
                Ok(0) => {
                    let _ = a_write.shutdown(Shutdown::Write);
                    break Ok(());
                }
                Ok(n) => {
                    if let Err(e) = a_write.write_all(&buf[..n]) {
                        let _ = a_write.shutdown(Shutdown::Both);
                        break Err(e);
                    }
                }
                Err(e) => {
                    let _ = a_write.shutdown(Shutdown::Both);
                    break Err(e);
                }
            }
        }
    });

    let r1 = h1.join().unwrap_or(Err(std::io::Error::new(std::io::ErrorKind::Other, "thread panic")));
    let r2 = h2.join().unwrap_or(Err(std::io::Error::new(std::io::ErrorKind::Other, "thread panic")));

    if let Err(e) = r1 {
        return Err(e);
    }
    if let Err(e) = r2 {
        return Err(e);
    }
    Ok(())
}
